// Writes every component's "Notes on what is in view" copy to NOTES_REVIEW.md for review.
//   node scripts/export_notes.mjs
// The source of truth stays frontend/src/simulation/narration.js (the NARRATION table); edit there.
import { writeFileSync } from 'node:fs'
import { NARRATED_KINDS, describeKind } from '../frontend/src/simulation/narration.js'

const lines = [
  '# Component notes — review sheet',
  '',
  'Generated by `node scripts/export_notes.mjs` from `frontend/src/simulation/narration.js`.',
  'Edit the `NARRATION` table there, not this file. Wording that depends on a node\'s own data',
  '(a filter\'s condition, a source type) is shown with that data empty.',
  '',
  '| Field | Shown as |',
  '| --- | --- |',
  '| What | what an event does here |',
  '| Why | why the component matters |',
  '| Caveat | the honest limit |',
  '',
]
for (const kind of NARRATED_KINDS) {
  const note = describeKind({ data: { kind } })
  lines.push(`## ${note.title} (\`${kind}\`)`, '', `**What.** ${note.what}`, '', `**Why.** ${note.why}`, '')
  if (note.caveat) lines.push(`**Caveat.** ${note.caveat}`, '')
  lines.push('**Review:** ☐ accurate  ☐ reworded  ☐ docs links added', '')
}
writeFileSync(new URL('../NOTES_REVIEW.md', import.meta.url), lines.join('\n'))
console.log(`wrote ${NARRATED_KINDS.length} kinds`)
